onLoad:
function onLoad() {
  MKXFORM.setFieldAttr("extra_row", 4);
  MKXFORM.setFieldAttr("extra_row", 6);
  var current = MKXFORM.getValue("fd_mode");
  if (current == 'A' || current == 'B' || current == 'C') {
    MKXFORM.setFieldAttr("extra_row", 5);
    MKXFORM.setFieldAttr("extra_row", 3);
  }
}

onChange:
function onChange(value) {
  MKXFORM.setFieldAttr("extra_row", 4);
  MKXFORM.setFieldAttr("extra_row", 6);
  if (value.indexOf("A") >= 0 || value.indexOf("B") >= 0 || value.indexOf("C") >= 0) {
    MKXFORM.setValue("fd_marker", "active");
    MKXFORM.setFieldAttr("extra_row", 5);
    MKXFORM.setFieldAttr("extra_row", 3);
  } else {
    MKXFORM.setValue("fd_marker", "");
  }
}
